const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const R=path.resolve(__dirname,'..'),main=path.resolve(process.env.ATOMIC_RULES_REPO||path.resolve(R,'../../..')),read=n=>fs.readFileSync(path.join(R,n),'utf8');
const file=path.join(main,'tests/withdraw-reason-last-complete.test.cjs'),prefix=fs.readFileSync(file,'utf8').split(/\ntest\(/)[0],old=new Function('require','__dirname',prefix+';return {fixture,prepare,request};')(require('node:module').createRequire(file),path.dirname(file));
const finance=require('./financial-fixture.cjs'),protectedSpecs=JSON.parse(read('protected-contract.json'));
const specs=JSON.parse(read('function-contract.json')),sql=phase=>fs.readFileSync(path.resolve(R,'../../../supabase/maintenance/withdraw-reason-atomic-rules.'+phase+'.sql'),'utf8');
async function setup(){const db=await old.fixture();try{await db.exec("set check_function_bodies=off;create function private.dashboard_admin_wg_sites()returns table(country text,platform text,country_code text,site_code text,currency text,timezone text)language sql stable as $$select null::text,null::text,null::text,null::text,null::text,null::text where false$$;create table private.withdraw_prepared_reason_compat(singleton boolean primary key,old_token text,new_token text,enabled boolean)");for(const s of [...specs.filter(x=>x.old_hash),...protectedSpecs.map(x=>({...x,name:x.signature.match(/private\.([^()]+)/)[1]}))]){await db.exec(read('baseline/'+s.name+'.sql'));await db.exec('revoke all on function '+s.signature+'from public,anon,authenticated,service_role');for(const acl of s.metadata.proacl||[])if(!acl.startsWith('postgres=')){const role=acl.split('=')[0];await db.exec('grant execute on function '+s.signature+'to '+role);}}await db.exec(read('baseline/withdraw_reason_dependency.sql'));await db.exec('revoke all on function private.withdraw_reason_dependency()from public,anon,authenticated,service_role');await finance.install(db);return db;}catch(e){await db.close();throw e;}}
const snapshot=async db=>(await db.query("select oid::regprocedure::text sig,to_jsonb(p)meta from pg_proc p where oid=any($1::regprocedure[])order by 1",[specs.filter(s=>s.old_hash).map(s=>s.signature)])).rows;
test('atomic install and rollback preserve exact metadata, unchanged financial tokens, idempotency and private helper ACL',async()=>{const db=await setup();try{const before=await snapshot(db),financialBefore=await finance.tokens(db);await db.exec(sql('install'));assert.deepEqual(await finance.tokens(db),financialBefore);const after=await snapshot(db);await db.exec(sql('install'));assert.deepEqual(await snapshot(db),after);for(const r of(await db.query(sql('postflight'))).rows){assert.equal(r.state,protectedSpecs.some(x=>x.signature===r.signature)?'protected':'candidate',r.signature);assert.equal(r.metadata_matches,true,r.signature);}for(const sig of specs.filter(x=>!x.old_hash).map(x=>x.signature))for(const role of['anon','authenticated','service_role'])assert.equal((await db.query('select has_function_privilege($1,$2,\'execute\')ok',[role,sig])).rows[0].ok,false);await db.exec(sql('rollback'));assert.deepEqual(await finance.tokens(db),financialBefore);assert.deepEqual(await snapshot(db),before);await db.exec(sql('rollback'));assert.deepEqual(await snapshot(db),before);}finally{await db.close();}});
test('metadata/definition drift refuses before any change and rollback also uses exact CAS',async()=>{for(const drift of ['acl','body']){const db=await setup();try{if(drift==='acl')await db.exec('grant execute on function private.dashboard_admin_live_blocking_details_cleaned(text)to anon');else await db.exec(read('baseline/dashboard_admin_live_blocking_details_cleaned.sql').replace('declare','declare\n -- synthetic drift'));const before=await snapshot(db);await assert.rejects(db.exec(sql('install')),/atomic_rules_(metadata|definition)_drift/);await db.exec('rollback');assert.deepEqual(await snapshot(db),before);}finally{await db.close();}}});
module.exports={setup,specs,sql,snapshot,old};
test('old combo artifact cannot be served through ready or last-complete paths after semantic switch',async()=>{const db=await setup();try{await db.exec(sql('install'));await old.prepare(db,'91CLUB','test.atom.legacy');await db.exec("insert into private.withdraw_prepared_reason_compat values(true,private.withdraw_reason_dependency(),private.withdraw_reason_dependency(),true)");const r=(await db.query('select private.dashboard_admin_live_withdraw_reasons($1)r',[old.request('91CLUB')])).rows[0].r;assert.equal(r.available,false);assert.equal(r.rows,null);assert.equal(r.publication,undefined);assert(['building','failed'].includes(r.prepared.status));}finally{await db.close();}});
test('real financial selector catches an unexpected financial function added during install and rolls back all changes',async()=>{const db=await setup();try{const before=await snapshot(db),tokens=await finance.tokens(db);const changed=sql('install').replace(' IF finance_before IS DISTINCT FROM '," EXECUTE 'create function private.dashboard_admin_wg_synthetic()returns int language sql as ''''select 1''''';\n IF finance_before IS DISTINCT FROM ".replaceAll("''''","''"));await assert.rejects(db.exec(changed),/atomic_rules_financial_dependency_changed/);await db.exec('rollback');assert.deepEqual(await snapshot(db),before);assert.deepEqual(await finance.tokens(db),tokens);assert.equal((await db.query("select to_regprocedure('private.dashboard_admin_wg_synthetic()')x")).rows[0].x,null);}finally{await db.close();}});

test('real dependency selectors reproduce the prior WG collision and isolate the new blocking helper',async()=>{const db=await setup();try{const old=await finance.tokens(db),reason=(await db.query('select private.withdraw_reason_dependency()v')).rows[0].v;const wg=read('baseline/dashboard_admin_wg_withdraw_reasons.sql');await db.exec('begin');await db.exec(wg.replace('AS $function$','AS $function$\n -- synthetic reason-reader change'));const collision=await finance.tokens(db);assert.notEqual(collision.commonIN,old.commonIN);assert.notEqual(collision.commonBR,old.commonBR);assert.equal(collision.withdraw,old.withdraw);assert.equal(collision.provider,old.provider);await db.exec('rollback');assert.deepEqual(await finance.tokens(db),old);await db.exec(sql('install'));assert.deepEqual(await finance.tokens(db),old);const installedReason=(await db.query('select private.withdraw_reason_dependency()v')).rows[0].v;assert.notEqual(installedReason,reason);await db.exec('begin');await db.exec(read('sql/withdraw_reason_wg_atomic.sql').replace('AS $function$','AS $function$\n -- synthetic atomic change'));assert.notEqual((await db.query('select private.withdraw_reason_dependency()v')).rows[0].v,installedReason);assert.deepEqual(await finance.tokens(db),old);await db.exec('rollback');await db.exec(sql('rollback'));assert.deepEqual(await finance.tokens(db),old);assert.equal((await db.query('select private.withdraw_reason_dependency()v')).rows[0].v,reason);}finally{await db.close();}});
test('unchanged WG body or ACL drift is refused by its protected contract',async()=>{for(const drift of ['body','acl']){const db=await setup();try{if(drift==='body')await db.exec(read('baseline/dashboard_admin_wg_withdraw_reasons.sql').replace('AS $function$','AS $function$\n -- synthetic unknown'));else await db.exec('grant execute on function private.dashboard_admin_wg_withdraw_reasons(jsonb,jsonb)to anon');const before=await snapshot(db);await assert.rejects(db.exec(sql('install')),/atomic_rules_protected_drift/);await db.exec('rollback');assert.deepEqual(await snapshot(db),before);}finally{await db.close();}}});
